// RailLog public snapshot API. A snapshot is never asserted to be the train's actual running day.
const Timetable=(()=>{
const cache=new Map();
function versionFor(versions,day){return versions.filter(v=>/^\d{4}\.\d{2}\.\d{2}$/.test(v)&&v.replaceAll('.','-')<=day).sort().at(-1)||null}
function section(stops,from,to,depart){const found=[];for(let i=0;i<stops.length;i++)if(stops[i].station_name===from)for(let j=i+1;j<stops.length;j++)if(stops[j].station_name===to)found.push(stops.slice(i,j+1));if(!found.length)throw Error('快照停站表不包含该方向的起终站');let selected=found;if(found.length>1&&depart)selected=found.filter(s=>s[0].start_time===depart);if(selected.length!==1)throw Error('同一车次有多个符合区间，请核对途经站');if(selected[0].some(s=>s.anomaly))throw Error('历史时刻表存在异常标记，请人工核对');return selected[0]}
async function get(path,signal){if(signal?.aborted)throw Error('已停止');if(cache.has(path))return cache.get(path);const c=new AbortController(),abort=()=>c.abort(),timer=setTimeout(abort,15000);signal?.addEventListener('abort',abort,{once:true});try{const r=await fetch('https://api.raillog.top'+path,{signal:c.signal});if(!r.ok)throw Error('时刻表服务返回 '+r.status);const d=await r.json();cache.set(path,d);return d}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort)}}
async function lookup(t,{signal}={}){if(t.time?.day==null)throw Error('缺少有效日期，无法选择历史时刻表');const train=String(t.raw['班次']||'').trim().toUpperCase();if(!/^[A-Z]?\d+(?:\/[A-Z]?\d+)*$/.test(train))throw Error('未填写可查询的中国铁路车次号');const versions=await get('/api/train-timetables/versions',signal),version=versionFor(versions,t.time.label);if(!version)throw Error('没有不晚于行程日期的时刻表快照');const data=await get('/api/train-timetables?'+new URLSearchParams({trainNumber:train,version}),signal);const stops=section(data.stops||[],t.from,t.to,t.time.departure);return{version,train:data.train_codes||train,stops,names:stops.map(s=>s.station_name),source:'RailLog 历史快照 '+version+'（参考，不保证当日实际开行）'}}
return{versionFor,section,lookup};})();
if(typeof module!=='undefined')module.exports=Timetable;
